def tuple_int_str(tuple_str):
    """Write a function to convert a tuple of string values to a tuple of integer values."""
    if isinstance(tuple_str, str):
        return int(tuple_str)
    if isinstance(tuple_str, (tuple, list)):
        return tuple(tuple_int_str(item) for item in tuple_str)
    return int(tuple_str)
